CREATE OR REPLACE FUNCTION public.fn_context_xep_hang(p_bang text, p_ban_ghi_id text, p_ly_do text DEFAULT 'tin_moi'::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_src public.context_nguon_thu_thap%rowtype;
  v_cfg public.context_cai_dat_to_chuc%rowtype;
  v_kh bigint; v_job bigint; v_luc timestamptz;
  g record; z record;
begin
  if p_bang = 'message_gom' then
    select m.id, m.account_id, m.contact_id, m.conversation_id, m.question_content, m.image_content,
           coalesce(m.question_last_at, m.question_first_at, m.created_at, now()) as luc
      into g from public.message_gom m where m.id = p_ban_ghi_id::uuid;
    if not found or g.contact_id is null then return null; end if;
    if public.fn_context_noi_dung_gom_hoi(g.question_content, g.image_content) is null then return null; end if;
    select s.* into v_src from public.context_nguon_thu_thap s
     where s.bang_nguon = 'public.message_gom' and s.account_id = g.account_id and s.is_active;
    if not found then return null; end if;
    if coalesce((v_src.dieu_kien_loc_tin ->> 'bo_qua_hoi_thoai_nhom')::boolean, true) and coalesce(g.conversation_id, '') like 'pzl_g_%' then return null; end if;
    select c.* into v_cfg from public.context_cai_dat_to_chuc c where c.organization_id = v_src.organization_id and c.is_active;
    if not found then return null; end if;
    v_kh := public.fn_context_nhan_dien_khach_gom(v_src.organization_id, g.contact_id);
    v_luc := g.luc;

  elsif p_bang = 'chat_zalo_message' then
    select m.id, m.organization_id, m.chat_zalo_account_organization_id as ao_id, m.chat_zalo_conversation_id as conv_id,
           m.direction, m.content_text, m.content_kind, m.is_recalled, m.deleted_at, m.deletion_scope,
           coalesce(m.zalo_sent_at, m.received_at) as luc, ac.conversation_type
      into z
      from public.chat_zalo_message m
      join public.chat_zalo_conversation c on c.id = m.chat_zalo_conversation_id
      join public.chat_zalo_account_conversation ac on ac.id = c.chat_zalo_account_conversation_id
     where m.id = p_ban_ghi_id::bigint;
    if not found or z.direction <> 'incoming' or coalesce(btrim(z.content_text), '') = ''
       or z.is_recalled or z.deleted_at is not null or z.deletion_scope is not null then return null; end if;
    select s.* into v_src from public.context_nguon_thu_thap s
     where s.bang_nguon = 'public.chat_zalo_message' and s.organization_id = z.organization_id and s.account_id is null and s.is_active;
    if not found then return null; end if;
    if coalesce((v_src.dieu_kien_loc_tin ->> 'chi_hoi_thoai_ca_nhan')::boolean, true) and z.conversation_type <> 'user' then return null; end if;
    if coalesce(v_src.dieu_kien_loc_tin -> 'bo_qua_tai_khoan_zalo_ids', '[]'::jsonb) @> to_jsonb(z.ao_id) then return null; end if;
    if jsonb_typeof(v_src.dieu_kien_loc_tin -> 'loai_noi_dung') = 'array'
       and not ((v_src.dieu_kien_loc_tin -> 'loai_noi_dung') ? z.content_kind) then return null; end if;
    select c.* into v_cfg from public.context_cai_dat_to_chuc c where c.organization_id = v_src.organization_id and c.is_active;
    if not found then return null; end if;
    v_kh := public.fn_context_nhan_dien_khach_zalo(z.organization_id, z.conv_id);
    v_luc := z.luc;
  else
    return null;
  end if;

  if v_kh is null then return null; end if;
  if exists (select 1 from public.context_khach_hang k where k.id = v_kh and k.la_noi_bo) then return null; end if;

  update public.context_khach_hang set khach_nhan_cuoi_luc = greatest(coalesce(khach_nhan_cuoi_luc, v_luc), v_luc)
   where id = v_kh and (khach_nhan_cuoi_luc is null or khach_nhan_cuoi_luc < v_luc);

  insert into public.context_lan_thu_thap (organization_id, khach_hang_id, nguon_thu_thap_id, ban_ghi_nguon_id, ly_do_chay, status, due_at)
  values (v_src.organization_id, v_kh, v_src.id, p_ban_ghi_id, coalesce(p_ly_do, 'tin_moi'), 'pending',
          now() + make_interval(mins => v_cfg.so_phut_cho_gom))
  on conflict (khach_hang_id, ly_do_chay) where status = 'pending'
  do update set
    due_at = least(excluded.due_at, public.context_lan_thu_thap.created_at + make_interval(mins => v_cfg.so_phut_cho_toi_da)),
    ban_ghi_nguon_id = excluded.ban_ghi_nguon_id,
    nguon_thu_thap_id = excluded.nguon_thu_thap_id
  returning id into v_job;
  return v_job;
end $function$
